1	import { access, cp, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
2	import { basename, dirname, join, relative, resolve } from 'pathe';
3	import { canonicalize, sha256 } from '../../../core/src/receipts/canonicalize.ts';
4	import {
5		parseWitnessReactHospitalrunReceipt,
6		REACT_HOSPITALRUN_CANONICAL_DIGEST,
7		REACT_HOSPITALRUN_FIXTURE,
8		REACT_HOSPITALRUN_RECEIPT_PATH,
9		REACT_HOSPITALRUN_RECEIPT_SHA256,
10		REACT_HOSPITALRUN_SOURCE,
11		renderWitnessReactHospitalrunReceipt,
12		WITNESS_REACT_HOSPITALRUN_CONSOLE_ERRORS,
13		WITNESS_REACT_HOSPITALRUN_SCHEMA,
14		WITNESS_REACT_HOSPITALRUN_SERVICE_WORKER_DIFFERENCE,
15		witnessReactHospitalrunBehaviorDigest,
16		witnessReactHospitalrunDigest,
17		witnessReactHospitalrunRawDigest,
18		type WitnessReactHospitalrunMutation,
19		type WitnessReactHospitalrunReceipt,
20		type WitnessReactHospitalrunRun,
21	} from '../../../core/src/receipts/witness-react-hospitalrun.ts';
22	import { executeReactHospitalrunWitnessRun, HOSPITALRUN_MUTATION_SEAM } from './real-app-run.ts';
23	import { verifyLinkedWitnessProvenance } from './provenance.ts';
24	
25	const root = resolve(import.meta.dirname, '../../../..');
26	const fixtureEvidence = join(root, 'evidence/runs/react-hospitalrun');
27	const witnessEvidence = join(root, 'evidence/runs/witness-react-hospitalrun');
28	const stageRoot = join(root, '.versionless/stage/witness-react-hospitalrun');
29	const sourceOutputs = {
30		baseline: join(root, '.versionless/work/react-hospitalrun/baseline/build-run1'),
31		migrated: join(root, '.versionless/work/react-hospitalrun/target/build-vite-run1'),
32	} as const;
33	
34	async function exists(path: string): Promise<boolean> {
35		return access(path).then(
36			() => true,
37			() => false,
38		);
39	}
40	
41	async function files(directory: string): Promise<string[]> {
42		const output: string[] = [];
43		for (const entry of await readdir(directory, { withFileTypes: true })) {
44			const path = join(directory, entry.name);
45			if (entry.isDirectory()) output.push(...(await files(path)));
46			else if (entry.isFile()) output.push(path);
47		}
48		return output.sort();
49	}
50	
51	async function stageInputs(): Promise<Record<'baseline' | 'migrated', string>> {
52		const lanes = join(stageRoot, 'lanes');
53		await rm(lanes, { recursive: true, force: true });
54		const staged = { baseline: join(lanes, 'baseline'), migrated: join(lanes, 'migrated') };
55		for (const lane of ['baseline', 'migrated'] as const) {
56			if (!(await exists(sourceOutputs[lane])))
57				throw new Error(`HospitalRun ${lane} production output is absent`);
58			await mkdir(dirname(staged[lane]), { recursive: true });
59			await cp(sourceOutputs[lane], staged[lane], { recursive: true, force: false });
60		}
61		return staged;
62	}
63	
64	async function executeRuns(
65		lanes: Record<'baseline' | 'migrated', string>,
66	): Promise<WitnessReactHospitalrunRun[]> {
67		const runs: WitnessReactHospitalrunRun[] = [];
68		for (const lane of ['baseline', 'migrated'] as const)
69			for (const pass of [1, 2] as const) {
70				const raw = await executeReactHospitalrunWitnessRun({
71					lane,
72					pass,
73					laneRoot: lanes[lane],
74					receiptRoot: join(stageRoot, 'receipts'),
75				});
76				const run = raw as WitnessReactHospitalrunRun;
77				if (run.semanticDigest !== witnessReactHospitalrunRawDigest(run))
78					throw new Error(`HospitalRun ${lane} pass ${pass} raw digest differs`);
79				runs.push({ ...run, behaviorDigest: witnessReactHospitalrunBehaviorDigest(run) });
80			}
81		if (new Set(runs.map((run) => run.behaviorDigest)).size !== 1)
82			throw new Error('HospitalRun baseline/migrated behavior parity differs');
83		return runs;
84	}
85	
86	/**
87	 * Byte mutation on the migrated build: locate the visible intake-success text
88	 * in the served module, overwrite it in place with an equal-length filler,
89	 * require the journey to go red on that exact assertion, restore the original
90	 * bytes, and require the restored journey to reproduce the parity behavior
91	 * digest.
92	 */
93	async function semanticMutation(
94		laneRoot: string,
95		behaviorDigest: string,
96	): Promise<WitnessReactHospitalrunMutation> {
97		const expected = Buffer.from(HOSPITALRUN_MUTATION_SEAM);
98		const candidates: Array<{ path: string; offset: number }> = [];
99		for (const path of await files(laneRoot)) {
100			const bytes = await readFile(path);
101			const offset = bytes.indexOf(expected);
102			if (offset < 0) continue;
103			if (bytes.lastIndexOf(expected) !== offset)
104				throw new Error('HospitalRun semantic seam is not unique within its file');
105			candidates.push({ path, offset });
106		}
107		const modules = candidates.filter((candidate) => candidate.path.endsWith('.js'));
108		const target = modules[0];
109		if (
110			modules.length !== 1 ||
111			target === undefined ||
112			canonicalize(candidates.map((candidate) => candidate.path).sort()) !==
113				canonicalize([target.path, `${target.path}.map`].sort())
114		)
115			throw new Error('HospitalRun semantic seam is not a single served module and its sourcemap');
116		const before = await readFile(target.path);
117		const mutated = Buffer.from(before);
118		Buffer.alloc(expected.length, 'X').copy(mutated, target.offset);
119		const beforeSha256 = sha256(before);
120		const mutatedSha256 = sha256(mutated);
121		let intendedFailure = false;
122		try {
123			await writeFile(target.path, mutated);
124			try {
125				await executeReactHospitalrunWitnessRun({
126					lane: 'migrated',
127					pass: 1,
128					laneRoot,
129					receiptRoot: join(stageRoot, 'mutation-receipt'),
130				});
131			} catch (error) {
132				const message = error instanceof Error ? error.message : String(error);
133				intendedFailure = message.includes(HOSPITALRUN_MUTATION_SEAM);
134			}
135		} finally {
136			await writeFile(target.path, before);
137		}
138		const afterRestoreSha256 = sha256(await readFile(target.path));
139		if (!intendedFailure || afterRestoreSha256 !== beforeSha256)
140			throw new Error('HospitalRun semantic mutation was not exact red and byte-restored');
141		const restored = (await executeReactHospitalrunWitnessRun({
142			lane: 'migrated',
143			pass: 1,
144			laneRoot,
145			receiptRoot: join(stageRoot, 'restoration-receipt'),
146		})) as WitnessReactHospitalrunRun;
147		const restoredBehaviorDigest = witnessReactHospitalrunBehaviorDigest(restored);
148		if (restoredBehaviorDigest !== behaviorDigest)
149			throw new Error('HospitalRun restored browser behavior differs');
150		return {
151			failure: 'witness-semantic-assertion',
152			intendedFailure: true,
153			lane: 'migrated',
154			seam: HOSPITALRUN_MUTATION_SEAM,
155			path: relative(laneRoot, target.path),
156			offset: target.offset,
157			beforeSha256,
158			mutatedSha256,
159			afterRestoreSha256,
160			restoredByteIdentically: true,
161			restoredRun: 'pass',
162			restoredBehaviorDigest,
163		};
164	}
165	
166	export async function runWitnessReactHospitalrun(): Promise<WitnessReactHospitalrunReceipt> {
167		if (
168			process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
169			process.env.NPM_CONFIG_OFFLINE !== 'true'
170		)
171			throw new Error('HospitalRun Witness requires dual offline controls');
172		if (await exists(witnessEvidence)) throw new Error('HospitalRun Witness output collision');
173		const provenance = await verifyLinkedWitnessProvenance(root);
174		const canonicalBytes = await readFile(join(root, REACT_HOSPITALRUN_RECEIPT_PATH));
175		const canonical = JSON.parse(canonicalBytes.toString('utf8')) as {
176			fixture?: unknown;
177			integrity: { canonicalDigest: string };
178		};
179		if (
180			canonical.fixture !== REACT_HOSPITALRUN_FIXTURE ||
181			canonical.integrity.canonicalDigest !== REACT_HOSPITALRUN_CANONICAL_DIGEST ||
182			sha256(canonicalBytes) !== REACT_HOSPITALRUN_RECEIPT_SHA256
183		)
184			throw new Error('HospitalRun canonical build receipt identity differs');
185		const lanes = await stageInputs();
186		const runs = await executeRuns(lanes);
187		const mutation = await semanticMutation(lanes.migrated, runs[0]!.behaviorDigest);
188		const blockedServiceWorker = {
189			registration: 'application-register-refused-by-context' as const,
190			checkpoints: runs[0]!.blockedServiceWorkerRuntime.checkpoints,
191			emittedOutputFiles: runs
192				.flatMap((run) => run.blockedServiceWorkerRuntime.emittedOutputFiles)
193				.filter(
194					(file, index, all) =>
195						all.findIndex((item) => canonicalize(item) === canonicalize(file)) === index,
196				)
197				.sort((left, right) => left.path.localeCompare(right.path)),
198			requests: [] as [],
199			workerEvents: [] as [],
200		};
201		const artifacts = join(fixtureEvidence, 'artifacts');
202		await mkdir(artifacts, { recursive: true });
203		await writeFile(join(artifacts, 'witness-journeys.json'), `${canonicalize(runs)}\n`, {
204			flag: 'wx',
205		});
206		await writeFile(join(artifacts, 'witness-mutation.json'), `${canonicalize(mutation)}\n`, {
207			flag: 'wx',
208		});
209		const receipt: WitnessReactHospitalrunReceipt = {
210			schemaVersion: WITNESS_REACT_HOSPITALRUN_SCHEMA,
211			result: 'pass',
212			fixture: REACT_HOSPITALRUN_FIXTURE,
213			source: REACT_HOSPITALRUN_SOURCE,
214			provenance,
215			canonicalReceipt: {
216				path: REACT_HOSPITALRUN_RECEIPT_PATH,
217				canonicalDigest: canonical.integrity.canonicalDigest,
218				sha256: sha256(canonicalBytes),
219			},
220			runs,
221			mutation,
222			blockedServiceWorker,
223			serviceWorkerDifference: WITNESS_REACT_HOSPITALRUN_SERVICE_WORKER_DIFFERENCE,
224			consoleErrors: WITNESS_REACT_HOSPITALRUN_CONSOLE_ERRORS,
225			scrollSurface: runs[0]!.scrollSurface,
226			persistence: {
227				store: 'browser-local-pouchdb',
228				stubbed: false,
229				survivesOnlineReload: true,
230			},
231			readiness: {
232				reactLineage: { ready: 1, total: 4, counted: false },
233				overall: { ready: 3, total: 12 },
234			},
235			locality: { mode: 'offline', successfulNonLoopback: 0, osWideIsolation: false },
236			nonclaims: [
237				'This is one React lineage under direct Witness and does not establish generic React or create-react-app support.',
238				'The React lineage readiness score is unchanged; this vertical is not counted before Judge audit.',
239				'The patient record is created inside the browser by the application itself against its own PouchDB store; no database was stubbed, seeded, or answered by the harness, and no real patient data is involved.',
