48	 * `src/index.tsx` calls `serviceWorker.register()` twice; the browser context
49	 * refuses service workers, so each load produces exactly two console errors,
50	 * and the two lanes fail differently — a real, recorded behavioral migration
51	 * difference:
52	 *
53	 * - the retained create-react-app baseline still emits `service-worker.js`, so
54	 *   the application reaches `navigator.serviceWorker.register()` and its own
55	 *   error handler logs the refusal;
56	 * - the migrated Vite build emits no worker script at all, so the application's
57	 *   `checkValidServiceWorker` probe 404s and never reaches registration.
58	 *
59	 * Message texts are recorded verbatim except for the ephemeral loopback origin,
60	 * which is normalized. Any console error outside this inventory fails the run.
61	 */
62	export const WITNESS_REACT_HOSPITALRUN_CONSOLE_ERRORS = Object.freeze({
63		baseline: Object.freeze([
64			Object.freeze({
65				message:
66					"Error during service worker registration: TypeError: Cannot set properties of undefined (setting 'onupdatefound')\n    at {production-static-origin}/static/js/main.963b07d9.chunk.js:1:205808",
67				count: 4,
68			}),
69		]),
70		migrated: Object.freeze([
71			Object.freeze({
72				message: 'Failed to load resource: the server responded with a status of 404 (Not Found)',
73				count: 4,
74			}),
75		]),
76	}) as Readonly<Record<'baseline' | 'migrated', readonly WitnessConsoleErrorInventoryEntry[]>>;
77	
78	/**
79	 * The baseline registers a worker script and the migrated build has none to
80	 * register. Recording the difference is the point: it is a genuine change in
81	 * observable behavior across the migration, not something to be normalized
82	 * away, and it is the only difference the two lanes exhibit.
83	 */
84	export const WITNESS_REACT_HOSPITALRUN_SERVICE_WORKER_DIFFERENCE = Object.freeze({
85		state: 'recorded-behavioral-migration-difference',
86		baseline: 'emits-service-worker-js-and-calls-register',
87		migrated: 'emits-no-service-worker-and-register-probe-404s',
88		registrationsInEitherLane: 0,
89		controllerInEitherLane: null,
90		cacheStorageNamesInEitherLane: 0,
91		masked: false,
92	});
93	
94	export type WitnessReactHospitalrunCheckpoint = {
95		phase: 'before-interactions' | 'after-interactions' | 'after-online-reload';
96		state: 'timeout';
97		registrations: 0;
98		controller: null;
99		cacheNames: [];
100		workerEvents: [];
101	};
102	
103	/**
104	 * Runtime blocked-service-worker observation.
105	 *
106	 * `emittedOutputFiles` is deliberately not required to be empty: the retained
107	 * create-react-app baseline ships a real `service-worker.js`, and erasing that
108	 * from the evidence would be masking. What is required is that no worker is
109	 * ever registered, controls the page, opens a cache, or emits a lifecycle event
110	 * in either lane or any pass.
111	 */
112	export type WitnessReactHospitalrunBlockedServiceWorker = {
113		registration: 'application-register-refused-by-context';
114		checkpoints: WitnessReactHospitalrunCheckpoint[];
115		emittedOutputFiles: Array<{ path: string; sha256: string }>;
116		requests: unknown[];
117		workerEvents: [];
118	};
119	
120	export type WitnessReactHospitalrunRun = WitnessRealAppRun & {
121		blockedServiceWorkerRuntime: WitnessReactHospitalrunBlockedServiceWorker;
122		consoleErrorInventory: WitnessConsoleErrorInventory;
123		scrollSurface: WitnessScrollSurface;
124		behaviorDigest: string;
125	};
126	
127	export type WitnessReactHospitalrunMutation = {
128		failure: 'witness-semantic-assertion';
129		intendedFailure: true;
130		lane: 'migrated';
131		seam: string;
132		path: string;
133		offset: number;
134		beforeSha256: string;
135		mutatedSha256: string;
136		afterRestoreSha256: string;
137		restoredByteIdentically: true;
138		restoredRun: 'pass';
139		restoredBehaviorDigest: string;
140	};
141	
142	export type WitnessReactHospitalrunReceipt = {
143		schemaVersion: typeof WITNESS_REACT_HOSPITALRUN_SCHEMA;
144		result: 'pass';
145		fixture: typeof REACT_HOSPITALRUN_FIXTURE;
146		source: typeof REACT_HOSPITALRUN_SOURCE;
147		provenance: Record<string, unknown>;
148		canonicalReceipt: { path: string; canonicalDigest: string; sha256: string };
149		runs: WitnessReactHospitalrunRun[];
150		mutation: WitnessReactHospitalrunMutation;
151		blockedServiceWorker: WitnessReactHospitalrunBlockedServiceWorker;
152		serviceWorkerDifference: typeof WITNESS_REACT_HOSPITALRUN_SERVICE_WORKER_DIFFERENCE;
153		consoleErrors: Readonly<
154			Record<'baseline' | 'migrated', readonly WitnessConsoleErrorInventoryEntry[]>
155		>;
156		scrollSurface: WitnessScrollSurface;
157		persistence: {
158			store: 'browser-local-pouchdb';
159			stubbed: false;
160			survivesOnlineReload: true;
161		};
162		readiness: {
163			reactLineage: { ready: 1; total: 4; counted: false };
164			overall: { ready: 3; total: 12 };
165		};
166		locality: { mode: 'offline'; successfulNonLoopback: 0; osWideIsolation: false };
167		nonclaims: string[];
168		integrity: { algorithm: 'sha256'; canonicalDigest: string };
169	};
170	
171	const exact = (left: unknown, right: unknown): boolean =>
172		canonicalize(left) === canonicalize(right);
173	
174	export function witnessReactHospitalrunRawDigest(
175		run: WitnessReactHospitalrunRun | WitnessRealAppRun,
176	): string {
177		const { pass: _pass, result: _result, semanticDigest: _semanticDigest, ...raw } = run;
178		const withoutBehavior = { ...raw } as Record<string, unknown>;
179		delete withoutBehavior.behaviorDigest;
180		return sha256(canonicalize(withoutBehavior));
181	}
182	
183	/**
184	 * Deterministic tracked-event floor.
185	 *
186	 * The typed, clicked, changed and keyed counts are exact and identical in every
187	 * lane and pass, so they are pinned. Incidental `mouseover` events depend on the
188	 * pointer path the host takes between the genuine hovers, so the count is
189	 * bounded from below by those hovers instead of being pinned to an unstable
190	 * number. The bound is checked, not erased.
191	 */
192	export const WITNESS_REACT_HOSPITALRUN_TRACKED_EVENTS = Object.freeze({
193		change: 2,
194		click: 12,
195		input: 16,
196		keydown: 16,
197		mouseoverAtLeast: 3,
198	});
199	
200	function trackedEventProjection(run: WitnessRealAppRun): Record<string, unknown> {
201		const counts = run.witnessRecord.trackedEventCounts;
202		const mouseover = counts.mouseover ?? 0;
203		if (
204			counts.change !== WITNESS_REACT_HOSPITALRUN_TRACKED_EVENTS.change ||
205			counts.click !== WITNESS_REACT_HOSPITALRUN_TRACKED_EVENTS.click ||
206			counts.input !== WITNESS_REACT_HOSPITALRUN_TRACKED_EVENTS.input ||
207			counts.keydown !== WITNESS_REACT_HOSPITALRUN_TRACKED_EVENTS.keydown ||
208			mouseover < WITNESS_REACT_HOSPITALRUN_TRACKED_EVENTS.mouseoverAtLeast ||
209			Object.keys(counts).sort().join(',') !== 'change,click,input,keydown,mouseover'
210		)
211			throw new Error('React HospitalRun tracked browser events differ');
212		return {
213			change: counts.change,
214			click: counts.click,
215			input: counts.input,
216			keydown: counts.keydown,
217			mouseover: `at-least-${WITNESS_REACT_HOSPITALRUN_TRACKED_EVENTS.mouseoverAtLeast}-genuine-hovers`,
218		};
219	}
220	
221	/**
222	 * Lane-independent behavior projection.
223	 *
224	 * Production bytes are lane-specific by construction, so the byte inventory
225	 * stays in the run record and out of this digest. The console-error inventory
226	 * is lane-specific on purpose — it is the recorded migration difference — so
227	 * the digest carries its shape and total rather than its lane-bound text, and
228	 * the text itself is verified exactly against the pinned inventory elsewhere.
229	 */
230	export function witnessReactHospitalrunBehaviorDigest(
231		run: WitnessReactHospitalrunRun | WitnessRealAppRun,
232	): string {
233		const blocked = (run as WitnessReactHospitalrunRun).blockedServiceWorkerRuntime;
234		const inventory = run.consoleErrorInventory;
235		return sha256(
236			canonicalize({
237				app: run.app,
238				framework: run.framework,
239				interactions: run.interactions,
240				assertions: run.assertions,
241				routes: run.routes,
242				trackedEvents: run.trackedEvents,
243				witnessRecord: {
244					...run.witnessRecord,
245					trackedEventCounts: trackedEventProjection(run),
246				},
247				cleanPage: run.cleanPage,
248				offlineEvidence: run.offlineEvidence,
249				servedStaticPolicy: {
250					transport: run.servedStatic.transport,
251					documentFallback: run.servedStatic.documentFallback,
252					missingAssets: run.servedStatic.missingAssets,
253					traversal: run.servedStatic.traversal,
254					byteIdentical: run.servedStatic.byteIdentical,
255					hmrControls: run.servedStatic.hmrControls,
256				},
257				blockedServiceWorkerRuntime: {
258					registration: blocked?.registration,
259					checkpoints: blocked?.checkpoints,
260					requests: blocked?.requests,
261					workerEvents: blocked?.workerEvents,
262				},
263				consoleErrorPolicy: {
264					policy: inventory?.policy,
265					outsideInventory: inventory?.outsideInventory,
266					total: inventory?.total,
267				},
268				scrollSurface: run.scrollSurface,
269				successfulNonLoopback: run.successfulNonLoopback,
270			}),
271		);
272	}
273	
274	export function witnessReactHospitalrunDigest(receipt: WitnessReactHospitalrunReceipt): string {
275		const copy = structuredClone(receipt);
276		copy.integrity.canonicalDigest = '';
277		return sha256(canonicalize(copy));
278	}
279	
280	function assertBlockedServiceWorker(
281		blocked: WitnessReactHospitalrunBlockedServiceWorker | undefined,
282		label: string,
283	): void {
284		if (
285			blocked === undefined ||
286			blocked.registration !== 'application-register-refused-by-context' ||
287			!Array.isArray(blocked.emittedOutputFiles) ||
288			!exact(blocked.requests, []) ||
289			!exact(blocked.workerEvents, []) ||
290			!Array.isArray(blocked.checkpoints) ||
291			blocked.checkpoints.length !== 3 ||
292			canonicalize(blocked.checkpoints.map((checkpoint) => checkpoint.phase)) !==
293				canonicalize(['before-interactions', 'after-interactions', 'after-online-reload']) ||
294			blocked.checkpoints.some(
295				(checkpoint) =>
296					checkpoint.state !== 'timeout' ||
297					checkpoint.registrations !== 0 ||
298					checkpoint.controller !== null ||
299					checkpoint.cacheNames.length !== 0 ||
300					checkpoint.workerEvents.length !== 0,
301			)
302		)
303			throw new Error(`React HospitalRun blocked service-worker evidence differs: ${label}`);
304	}
305	
306	function assertConsoleErrorInventory(
307		inventory: WitnessConsoleErrorInventory | undefined,
308		lane: 'baseline' | 'migrated',
309		label: string,
310	): void {
311		const pinned = [...WITNESS_REACT_HOSPITALRUN_CONSOLE_ERRORS[lane]].map((entry) => ({
312			message: entry.message,
313			count: entry.count,
314		}));
315		if (
316			inventory === undefined ||
317			inventory.policy !== 'exact-app-scoped-expected-console-errors' ||
318			inventory.originPlaceholder !== '{production-static-origin}' ||
319			!exact(inventory.outsideInventory, []) ||
320			!exact(inventory.expected, pinned) ||
321			!exact(inventory.observed, pinned) ||
322			inventory.total !== pinned.reduce((sum, entry) => sum + entry.count, 0)
323		)
324			throw new Error(`React HospitalRun console-error inventory differs: ${label}`);
325	}
326	
327	function assertScrollSurface(surface: WitnessScrollSurface | undefined, label: string): void {
328		if (
329			surface === undefined ||
330			surface.state !== 'measured-genuine-viewport-scroll' ||
331			surface.route !== '/appointments' ||
332			surface.viewport.width !== 1280 ||
333			surface.viewport.height !== 720 ||
334			surface.clientHeight !== 720 ||
335			surface.scrollHeight <= surface.clientHeight ||
336			surface.wheelDeltaY <= 0 ||
337			surface.scrolledFromTop !== true ||
338			surface.scrolled !== true
339		)
340			throw new Error(`React HospitalRun scroll surface differs: ${label}`);
341	}
342	
343	export function parseWitnessReactHospitalrunReceipt(
344		value: unknown,
345	): WitnessReactHospitalrunReceipt {
346		if (value === null || typeof value !== 'object' || Array.isArray(value))
347			throw new Error('React HospitalRun Witness receipt must be an object');
348		const receipt = value as WitnessReactHospitalrunReceipt;
349		const expectedRuns = new Set(['baseline:1', 'baseline:2', 'migrated:1', 'migrated:2']);
350		const behaviors = new Set<string>();
351		if (
352			receipt.schemaVersion !== WITNESS_REACT_HOSPITALRUN_SCHEMA ||
353			receipt.result !== 'pass' ||
354			receipt.fixture !== REACT_HOSPITALRUN_FIXTURE ||
355			!exact(receipt.source, REACT_HOSPITALRUN_SOURCE) ||
356			receipt.canonicalReceipt?.path !== REACT_HOSPITALRUN_RECEIPT_PATH ||
357			receipt.canonicalReceipt.canonicalDigest !== REACT_HOSPITALRUN_CANONICAL_DIGEST ||
358			receipt.canonicalReceipt.sha256 !== REACT_HOSPITALRUN_RECEIPT_SHA256 ||
359			!Array.isArray(receipt.runs) ||
360			receipt.runs.length !== 4
361		)
362			throw new Error('React HospitalRun Witness binding differs');
363		for (const run of receipt.runs) {
364			const key = `${run.lane}:${run.pass}`;
365			if (
366				!expectedRuns.delete(key) ||
367				run.app !== 'react-hospitalrun' ||
368				run.framework !== 'react' ||
369				run.result !== 'pass' ||
370				run.cleanPage !== true ||
371				run.successfulNonLoopback !== 0 ||
372				run.witnessRecord.pageErrors !== 0 ||
373				run.witnessRecord.failedRequests !== 0 ||
374				run.witnessRecord.consoleErrors !== run.consoleErrorInventory?.total ||
375				run.offlineEvidence.state !== 'not-applicable' ||
376				run.observerFinalization.workerEvents.length !== 0 ||
377				run.semanticDigest !== witnessReactHospitalrunRawDigest(run) ||
378				run.behaviorDigest !== witnessReactHospitalrunBehaviorDigest(run) ||
379				!exact(run.routes, ['/patients'])
380			)
381				throw new Error(`React HospitalRun Witness run differs: ${key}`);
382			assertBlockedServiceWorker(run.blockedServiceWorkerRuntime, key);
383			assertConsoleErrorInventory(run.consoleErrorInventory, run.lane, key);
384			assertScrollSurface(run.scrollSurface, key);
385			behaviors.add(run.behaviorDigest);
386		}
387		assertBlockedServiceWorker(receipt.blockedServiceWorker, 'receipt');
388		assertScrollSurface(receipt.scrollSurface, 'receipt');
389		if (
390			expectedRuns.size !== 0 ||
391			behaviors.size !== 1 ||
392			!exact(receipt.consoleErrors, WITNESS_REACT_HOSPITALRUN_CONSOLE_ERRORS) ||
393			!exact(
394				receipt.serviceWorkerDifference,
395				WITNESS_REACT_HOSPITALRUN_SERVICE_WORKER_DIFFERENCE,
396			) ||
397			!exact(receipt.persistence, {
398				store: 'browser-local-pouchdb',
399				stubbed: false,
400				survivesOnlineReload: true,
401			}) ||
402			receipt.mutation?.intendedFailure !== true ||
403			receipt.mutation.failure !== 'witness-semantic-assertion' ||
404			receipt.mutation.lane !== 'migrated' ||
405			receipt.mutation.restoredByteIdentically !== true ||
406			receipt.mutation.restoredRun !== 'pass' ||
407			receipt.mutation.beforeSha256 !== receipt.mutation.afterRestoreSha256 ||
408			receipt.mutation.beforeSha256 === receipt.mutation.mutatedSha256 ||
409			!behaviors.has(receipt.mutation.restoredBehaviorDigest) ||
410			!exact(receipt.readiness, {
411				reactLineage: { ready: 1, total: 4, counted: false },
412				overall: { ready: 3, total: 12 },
413			}) ||
414			receipt.locality?.mode !== 'offline' ||
415			receipt.locality.successfulNonLoopback !== 0 ||
416			receipt.locality.osWideIsolation !== false ||
417			!Array.isArray(receipt.nonclaims) ||
418			receipt.nonclaims.length === 0 ||
419			receipt.integrity?.algorithm !== 'sha256' ||
420			receipt.integrity.canonicalDigest !== witnessReactHospitalrunDigest(receipt)
421		)
422			throw new Error('React HospitalRun Witness integrity differs');
423		return receipt;
424	}
425	
426	function uniqueSorted(values: readonly string[]): string[] {
427		return [...new Set(values)].sort();
428	}
429	
430	export function renderWitnessReactHospitalrunReceipt(
431		receipt: WitnessReactHospitalrunReceipt,
432	): string {
433		const emitted = receipt.runs.flatMap((run) =>
434			run.blockedServiceWorkerRuntime.emittedOutputFiles.map((file) => file.path),
435		);
436		const inventoryLine = (lane: 'baseline' | 'migrated'): string =>
437			receipt.consoleErrors[lane]
438				.map((entry) => `${entry.count}x \`${entry.message.split('\n')[0]}\``)
439				.join('; ');
440		return `# HospitalRun v2.0.0-alpha.7 — direct Witness browser proof
441	
442	- Result: pass
443	- Canonical SHA-256: ${receipt.integrity.canonicalDigest}
444	- Runs: 2 baseline + 2 migrated production-static browser journeys
445	- Behavioral parity: ${receipt.runs[0]!.behaviorDigest}
446	- Journey: new-patient intake into the browser-local PouchDB store, success toast, patient row, patient record sub-tabs, labs / incidents / imaging department routes, appointment schedule with a real wheel scroll, and an online reload the created record survives
447	- Persistence: ${receipt.persistence.store}, stubbed: ${String(receipt.persistence.stubbed)}, survives an online reload: ${String(receipt.persistence.survivesOnlineReload)}
448	- Service worker: the application's own \`serviceWorker.register()\` is refused by the browser context; zero registrations, controller, CacheStorage names, lifecycle events, and worker requests at three checkpoints in every pass
449	- Recorded migration difference: baseline ${receipt.serviceWorkerDifference.baseline}; migrated ${receipt.serviceWorkerDifference.migrated}; masked: ${String(receipt.serviceWorkerDifference.masked)}
450	- Console-error inventory (exact, whole journey, per lane) — baseline: ${inventoryLine('baseline')}; migrated: ${inventoryLine('migrated')}
451	- Retained but never-controlling worker output: ${emitted.length === 0 ? 'none' : uniqueSorted(emitted).join(', ')}
452	- Mutation proof: \`${receipt.mutation.seam}\` in \`${receipt.mutation.path}\` at offset ${receipt.mutation.offset} made the journey red, byte-identical restoration made it green again
453	- Scroll: ${receipt.scrollSurface.state} on ${receipt.scrollSurface.route} — scrollHeight ${receipt.scrollSurface.scrollHeight} against clientHeight ${receipt.scrollSurface.clientHeight} at ${receipt.scrollSurface.viewport.width}x${receipt.scrollSurface.viewport.height}
454	- React lineage readiness: unchanged at ${receipt.readiness.reactLineage.ready}/${receipt.readiness.reactLineage.total}; this vertical is not counted
455	
456	${receipt.nonclaims.map((claim) => `- ${claim}`).join('\n')}
457	`;
458	}
459	
460	export function witnessReactHospitalrunAggregateMember(digestValue: string) {
461		return {
462			id: 'witness-react-hospitalrun',
463			framework: 'react',
464			track: 'production-readiness-direct-witness-create-react-app-to-vite8',
465			bundler: 'webpack-4.42.0-to-vite-8.0.16',
466			runtime: 'node-12.14.1-to-node-24.15.0',
467			result: 'pass',
468			receipt: WITNESS_REACT_HOSPITALRUN_RECEIPT_PATH,
469			digest: digestValue,
470		};
471	}
472	
473	export async function verifyWitnessReactHospitalrunEvidence(rootDir = '.') {
474		const root = resolve(rootDir);
475		const receiptPath = join(root, WITNESS_REACT_HOSPITALRUN_RECEIPT_PATH);
476		const receipt = parseWitnessReactHospitalrunReceipt(
477			JSON.parse(await readFile(receiptPath, 'utf8')),
478		);
479		const canonicalBytes = await readFile(join(root, receipt.canonicalReceipt.path));
480		if (sha256(canonicalBytes) !== receipt.canonicalReceipt.sha256)
481			throw new Error('React HospitalRun canonical receipt bytes drifted');
482		const canonical = JSON.parse(canonicalBytes.toString('utf8')) as {
483			runId?: unknown;
484			fixture?: unknown;
485			integrity?: { canonicalDigest?: unknown };
486		};
487		if (
488			canonical.runId !== REACT_HOSPITALRUN_RUN_ID ||
489			canonical.fixture !== REACT_HOSPITALRUN_FIXTURE ||
490			canonical.integrity?.canonicalDigest !== receipt.canonicalReceipt.canonicalDigest
491		)
492			throw new Error('React HospitalRun canonical receipt identity differs');
493		if (
494			(await readFile(join(dirname(receiptPath), 'receipt.md'), 'utf8')) !==
495			renderWitnessReactHospitalrunReceipt(receipt)
496		)
497			throw new Error('React HospitalRun human Witness receipt differs');
498		return {
499			valid: true as const,
500			digest: receipt.integrity.canonicalDigest,
501			artifacts: 0,
502			receipt,
503		};
504	}
