/**
 * One observed service-worker-script event, stripped of the two fields that
 * cannot reproduce: the wall-clock timestamp and the run-global sequence
 * number, which counts every other asset the lane happens to load. What
 * remains — who observed it, in what phase, for which path, with what detail —
 * is the substance of the observation and is identical run to run.
 */
export type WitnessServiceWorkerRequestEvent = {
	source: string;
	phase: string;
	urlPath: string | null;
	detail: Record<string, boolean | number | string | null>;
};
/** The same event with the number of times it was observed, for exact accounting. */
export type WitnessServiceWorkerRequestTally = WitnessServiceWorkerRequestEvent & {
	count: number;
};

export type WitnessRealAppRun = {

/**
 * Drops the wall clock and the run-global sequence number from observed
 * service-worker events, keeping every field that describes what was actually
 * observed. Nothing is filtered out here — the whole ordered trace survives, it
 * simply becomes reproducible.
 */
function projectServiceWorkerEvents(
	events: readonly WitnessDifferentialEvent[],
): WitnessServiceWorkerRequestEvent[] {
	return events.map((event) => ({
		source: event.source,
		phase: event.phase,
		urlPath: event.urlPath,
		detail: event.detail,
	}));
}

/** Exact multiset of the projected trace, for verification against a pinned tally. */
function tallyServiceWorkerEvents(
	events: readonly WitnessServiceWorkerRequestEvent[],
): WitnessServiceWorkerRequestTally[] {
	const counts = new Map<string, WitnessServiceWorkerRequestTally>();
	for (const event of events) {
		const key = canonicalize(event);
		const existing = counts.get(key);
		if (existing === undefined) counts.set(key, { ...event, count: 1 });
		else existing.count += 1;
	}
	return [...counts]
		.sort(([left], [right]) => compareUtf16CodeUnits(left, right))
		.map(([, tally]) => tally);
}

